import{_ as n,a0 as r,w as o,s as p,I as s,x as t,a1 as l,A as a,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse(`{"title":"GNOME的文件管理器将对用户更加友好 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME的文件管理器将对用户更加友好 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME的文件管理器将对用户更加友好 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME的文件管理器将对用户更加友好 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/GNOME's File Manager Will Be More User Friendly","title":"GNOME的文件管理器将对用户更加友好","tag":"201312","desc":""},"relativePath":"201312/GNOME's File Manager Will Be More User Friendly.md","filePath":"[post].md"}`),m={name:"201312/GNOME's File Manager Will Be More User Friendly.md"};function d(M,e,N,g,f,E){const i=r("Link");return o(),p("div",null,[e[14]||(e[14]=s("h1",{id:"gnome的文件管理器将对用户更加友好",tabindex:"-1"},[t("GNOME的文件管理器将对用户更加友好 "),s("a",{class:"header-anchor",href:"#gnome的文件管理器将对用户更加友好","aria-label":"Permalink to “GNOME的文件管理器将对用户更加友好”"},"​")],-1)),s("p",null,[s("strong",null,[e[1]||(e[1]=t("几天前，GNOME的设计师Allan Day在博客里发布了一篇超长博文，介绍了",-1)),l(i,{href:"http://afaikblog.wordpress.com/2013/12/11/nautilus-next/"},{default:a(()=>[...e[0]||(e[0]=[t("GNOME桌面环境下的下一代Nautilus文件管理器",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))])]),e[15]||(e[15]=u('<p>本文将为读者简短介绍即将发布的Nautilus都实现了哪些新的设计功能，这些新功能也将成为GNOME3.12桌面环境的组成部分。</p><p>很显然，GNOME开发小组对大家一直关注的桌面环境的默认文件管理器进行了美化改进，另外将一些后台功能改放到了显著位置，使其对新用户更加明显。</p><p>不管你是否相信，事实是，有非常多的新用户尝试探索Linux世界之奥秘的时候，面对Nautilus却一筹莫展，他们不知道如何复制、粘贴、重命名、移动，甚至不知道如何访问他们的文件…… 这是一个非常窘迫、亟待解决的大问题！</p><p>因此，Nautilus文件管理器的未来版本将着重解决这些问题，包括图标响应、列表视图、更大更清晰的缩略图，以及更好用的缩放层级等等，通过这些，你可以更容易地组织你的文件。同时，更新后的视图菜单也实现了更优秀的控制操作。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-2.png" alt="Nautilus list view"><em>Nautilus列表视图</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-3.png" alt="Nautilus grid view"><em>Nautilus图标视图</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-4.png" alt="Nautilus gear menu"><em>Nautilus齿轮菜单</em></p><p>Nautilus将要实现的另一个重要特性是各种各样好用的按钮。例如“复制到…、移动到…、创建新文件夹、以…打开”等等，它们将使文件操作变得更加友好。同时，文件预览将变得更加直接，包括一个备受期待的导航功能，它能使照片或文档浏览变得更加容易。</p><p>不仅如此，侧边栏的可定制化程度也会更高，它将允许用户添加或删除网络设备、网络分区，或着是与它们的远程连接，使整个侧边栏变得更加整洁（这一改进对于像本译者这样的强迫症患者来说多么福音啊~）。新增加的“收藏”标签可用于访问所有你最喜欢的文件，还有改进后的“内容选择功能”，允许用户从多个来源选择项目。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-5.png" alt="Nautilus add drive dialog"><em>Nautilus添加设备对话框</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-6.png" alt="Nautilus content selection"><em>Nautilus内容选择</em></p><p>很不幸，目前还没有渠道供我们编译测试最新的Nautilus，但开发版发布的时候，我们会第一时间通知大家。最后提醒大家，Nautilus同时还是Ubuntu Linux的默认文件管理器哦~</p><hr>',13)),s("p",null,[e[4]||(e[4]=t("via: ",-1)),l(i,{href:"http://news.softpedia.com/news/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360.shtml"},{default:a(()=>[...e[3]||(e[3]=[t("http://news.softpedia.com/news/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360.shtml",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=t("译者：",-1)),l(i,{href:"http://blog.csdn.net/tinyeyeser"},{default:a(()=>[...e[5]||(e[5]=[t("Mr小眼儿",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),l(i,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[6]||(e[6]=[t("Caroline",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),l(i,{href:"http://linux.cn/"},{default:a(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const G=n(m,[["render",d]]);export{F as __pageData,G as default};
